use genex::prelude::*;
use genex::render::{Decal, IrradianceVolume, ReflectionProbe};

fn draw(world: &World, frame: &mut Frame) {
    for room in &world.rooms {
        // One box per room, floor to ceiling, declared every frame: the cube and the grid bake once.
        let eye = vec3((room.min.x + room.max.x) * 0.5, room.min.y + 1.6, (room.min.z + room.max.z) * 0.5);
        frame.reflection_probe(&ReflectionProbe::new(room.min, room.max).with_capture(eye).with_blend(0.4));
        frame.irradiance_volume(&IrradianceVolume::new(room.min, room.max).with_blend(0.3));
    }
    frame.tag("poster");
    frame.decal(&Decal::on_wall(world.poster_at, vec3(0.0, 0.0, 1.0), 0.8, 1.2).with_base_texture("decals/poster.png"));
    frame.tag("puddle");
    frame.decal(
        &Decal::on_ground(world.puddle_at, 1.6, 1.0)
            .with_base_texture("decals/puddle.png")
            .with_color(Color::rgb(40, 40, 45))
            .with_roughness(0.04)
            .with_flatten(1.0),
    );
}
